Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "transform": [
    {"filter": "datum[''Total Reviews''] > 10"},
    {"window": [{"op": "lag", "field": "Total Reviews", "as": "prev"}], "sort": [{"field": "Year"}]},
    {"calculate": "datum.prev ? (datum[''Total Reviews''] - datum.prev) / datum.prev : null", "as": "yoy"},
    {"joinaggregate": [{"op": "max", "field": "Total Reviews", "as": "peak"}]}
  ],
  "hconcat": [
    {
      "width": 190, "height": 130,
      "layer": [
        {
          "transform": [{"aggregate": [{"op": "count", "as": "n"}]}],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 0, "fontSize": 11, "letterSpacing": 1.5, "color": "#8A7F6E", "text": "REVIEWS"}
        },
        {
          "transform": [{"aggregate": [{"op": "sum", "field": "Total Reviews", "as": "total"}]}],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 22, "fontSize": 34, "fontWeight": 600, "color": "#14617E"},
          "encoding": {"text": {"field": "total", "format": ".4~s"}}
        },
        {
          "transform": [{"filter": "datum[''Total Reviews''] == datum.peak"}, {"calculate": "''Peak '' + datum.Year + '': '' + format(datum[''Total Reviews''], ''.3~s'')", "as": "t"}],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 76, "fontSize": 12, "color": "#6B6255"},
          "encoding": {"text": {"field": "t"}}
        },
        {
          "transform": [{"filter": "datum.Year == 2020"}, {"calculate": "''2020: '' + format(datum.yoy, ''+.0%'') + '' (COVID-19)''", "as": "t"}],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 96, "fontSize": 12, "fontWeight": 600, "color": "#B8860B"},
          "encoding": {"text": {"field": "t"}}
        }
      ]
    },
    {
      "width": 340, "height": 130,
      "mark": {"type": "bar", "cornerRadiusTopLeft": 3, "cornerRadiusTopRight": 3},
      "encoding": {
        "x": {"field": "Year", "type": "ordinal", "axis": {"title": null, "labelAngle": 0, "domain": false, "ticks": false, "labelColor": "#8A7F6E", "labelFontSize": 10, "labelExpr": "\"''\" + substring(datum.label, 2)"}},
        "y": {"field": "Total Reviews", "type": "quantitative", "axis": null},
        "color": {"condition": {"test": "datum.Year == 2020", "value": "#F2B632"}, "value": "#14617E"},
        "tooltip": [
          {"field": "Year"},
          {"field": "Total Reviews", "title": "Reviews", "format": ","},
          {"field": "yoy", "title": "vs previous year", "format": "+.0%"}
        ]
      }
    }
  ],
  "spacing": 16,
  "config": {"view": {"stroke": null}, "font": "Segoe UI"}
}'
